(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma store_ok_agree : forall (k : nat) (M M' : word -> option byte) (w : word),
  U w + Z.of_nat k <= 2 ^ 64 ->
  (forall x : word, U w <= U x < U w + Z.of_nat k -> M' x = M x) ->
  store_ok ASEGS M w k = true -> store_ok ASEGS M' w k = true.
